-- The two checklists published on 2026-11-04: When Someone at Work Treats You
-- Badly (Bullying) and Cooking for One (Cooking).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-04`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-someone-at-work-treats-you-badly', 'When Someone at Work Treats You Badly', 'For the point where someone at work has gone past rudeness and you are starting to doubt yourself. It gets the incidents written down with dates, the policy read before you report, one person told outside work, and a line set for when to leave.', 'Bullying', '["Write down each incident with the date and the words used — a pattern on paper is what other people can act on.", "Keep that record somewhere that is not their system — a work laptop can stop being yours overnight.", "Name one person who saw it — a second account turns your word into a record.", "Read your employer''s policy before you report anything — knowing the steps stops them being used on you.", "Answer in writing wherever you can — an email leaves a trail that a corridor conversation does not.", "Separate what they said from what you believe about yourself — how they act is information about them.", "Tell one person outside work what is happening — carrying it alone is what makes it start to feel deserved.", "Find out what your options are elsewhere — a live alternative changes how it feels to stay.", "Decide what would make you leave and write it down — a line set in advance is harder to talk yourself past."]'::jsonb, 'as needed', array['Work', 'Assertiveness', 'Self-Esteem']::text[], 1, '2026-11-04T16:00:00+00:00'::timestamptz),
  ('cooking-for-one', 'Cooking for One', 'For anyone feeding themselves alone, when cooking for one person stops seeming worth the trouble. It settles on three meals you actually like, shops for four days, keeps the freezer stocked for bad nights, and lets toast be dinner sometimes.', 'Cooking', '["Pick three meals you actually like and learn them cold — a short repertoire beats a long list you never cook.", "Shop for four days rather than seven — a fridge you empty costs less than one you clear out.", "Cook the full amount and keep half for tomorrow — the second night is the whole point of cooking once.", "Keep three things in the freezer for the worst nights — a bad evening should not also be a hungry one.", "Eat at the table with the screen off once this week — a meal you sit down to lands differently.", "Put something fresh on the plate each day — one green thing is the whole ambition here.", "Cook for somebody else once a month — feeding a person is a different act from feeding yourself.", "Wash up before you sit down — the kitchen you walk into tomorrow decides whether you cook.", "Let a bad night be toast — cooking for one does not have to be earned every evening."]'::jsonb, 'weekly', array['Food', 'Self-Care', 'Loneliness']::text[], 1, '2026-11-04T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
